using System.Diagnostics;
using System.Text;
using ConvertApi.Core.Conversion;
using ConvertApi.Core.Formats;
using ConvertApi.Worker.Converters;

namespace ConvertApi.UnitTests.Worker;

/// <summary>
/// Runs the real FFmpeg on media generated by FFmpeg itself (a test pattern and a sine tone),
/// so no binary sample lives in the repository. Skipped when FFmpeg is not installed:
/// set FFMPEG_PATH or put ffmpeg on the PATH.
/// </summary>
public sealed class FfmpegConverterTests : IDisposable
{
    private static readonly string Ffmpeg = Environment.GetEnvironmentVariable("FFMPEG_PATH") ?? "ffmpeg";

    private readonly string _directory = Path.Combine(Path.GetTempPath(), "convertapi-tests", Guid.NewGuid().ToString("N"));
    private readonly FfmpegConverter _converter = new(Ffmpeg);

    public FfmpegConverterTests()
    {
        Directory.CreateDirectory(_directory);
    }

    private static CancellationToken Ct => TestContext.Current.CancellationToken;

    public void Dispose() => Directory.Delete(_directory, recursive: true);

    [Theory]
    [InlineData("mp4", "mp3")]
    [InlineData("mp4", "wav")]
    [InlineData("mp4", "webm")]
    [InlineData("mp4", "gif")]
    [InlineData("mkv", "mp4")]
    [InlineData("wav", "mp3")]
    [InlineData("wav", "flac")]
    [InlineData("wav", "ogg")]
    [InlineData("wav", "aac")]
    [InlineData("mp3", "wav")]
    public async Task Convert_ProducesAFileOfTheTargetFormat(string source, string target)
    {
        var input = await SampleAsync(source);
        var request = new ConversionRequest(input, Output(target), source, target);

        await _converter.ConvertAsync(request, Ct);

        var header = (await File.ReadAllBytesAsync(request.OutputPath, Ct)).AsSpan(0, FileSignatureDetector.HeaderLength);
        Assert.Equal(target, FileSignatureDetector.Detect(header));
    }

    [Fact]
    public async Task Metadata_IsNotCopiedToTheResult()
    {
        var input = await SampleAsync("mp3", "-metadata", "title=Secret-Title-1234");
        var request = new ConversionRequest(input, Output("mp3"), "mp3", "mp3");

        await _converter.ConvertAsync(request, Ct);

        var output = Encoding.Latin1.GetString(await File.ReadAllBytesAsync(request.OutputPath, Ct));
        Assert.DoesNotContain("Secret-Title-1234", output, StringComparison.Ordinal);
    }

    [Fact]
    public async Task ACorruptFile_IsRejected()
    {
        var input = Path.Combine(_directory, "corrupt.mp4");
        await File.WriteAllBytesAsync(input, [0, 0, 0, 0x20, 0x66, 0x74, 0x79, 0x70, 0x69, 0x73, 0x6F, 0x6D, 1, 2, 3, 4], Ct);
        var request = new ConversionRequest(input, Output("mp3"), "mp4", "mp3");

        var error = await Assert.ThrowsAsync<ConversionFailedException>(() => _converter.ConvertAsync(request, Ct));

        Assert.Contains("mp4", error.Message, StringComparison.Ordinal);
        Assert.False(File.Exists(request.OutputPath));
    }

    [Fact]
    public async Task AFileOfAnotherFormat_IsRejected_BecauseTheDetectedFormatIsForced()
    {
        var wav = await SampleAsync("wav");
        var request = new ConversionRequest(wav, Output("mp3"), "mp4", "mp3");

        await Assert.ThrowsAsync<ConversionFailedException>(() => _converter.ConvertAsync(request, Ct));
    }

    [Fact]
    public async Task Cancelling_StopsFfmpeg()
    {
        var input = await SampleAsync("mp4", seconds: 20);
        var request = new ConversionRequest(input, Output("webm"), "mp4", "webm");
        using var cancel = CancellationTokenSource.CreateLinkedTokenSource(Ct);
        cancel.CancelAfter(TimeSpan.FromMilliseconds(300));
        var running = Process.GetProcessesByName("ffmpeg").Length;

        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => _converter.ConvertAsync(request, cancel.Token));

        await Task.Delay(500, Ct);
        Assert.Equal(running, Process.GetProcessesByName("ffmpeg").Length);
    }

    [Fact]
    public async Task AnOutputBiggerThanTheLimit_IsStoppedAndRejected()
    {
        var input = await SampleAsync("wav");
        var converter = new FfmpegConverter(Ffmpeg, maxOutputBytes: 20_000);
        var request = new ConversionRequest(input, Output("wav"), "wav", "wav");

        var error = await Assert.ThrowsAsync<ConversionFailedException>(() => converter.ConvertAsync(request, Ct));

        Assert.Contains("larger", error.Message, StringComparison.Ordinal);
        Assert.False(File.Exists(request.OutputPath));
    }

    [Fact]
    public async Task MediaLongerThanTheLimit_IsCutAtTheLimit()
    {
        var input = await SampleAsync("wav", seconds: 4);
        var converter = new FfmpegConverter(Ffmpeg, maxMediaDuration: TimeSpan.FromSeconds(1));
        var request = new ConversionRequest(input, Output("wav"), "wav", "wav");

        await converter.ConvertAsync(request, Ct);

        Assert.InRange(await DurationAsync(request.OutputPath), 0.9, 1.1);
    }

    [Fact]
    public async Task AVeryLargeVideo_IsScaledDownToFullHd()
    {
        var input = await SampleAsync("mp4", seconds: 1, size: "2560x1440");
        var request = new ConversionRequest(input, Output("mp4"), "mp4", "mp4");

        await _converter.ConvertAsync(request, Ct);

        Assert.Equal("1920x1080", await ProbeAsync(request.OutputPath, "stream=width,height", "-select_streams", "v:0", "x"));
    }

    [Fact]
    public async Task ARelativePath_IsRefused_SoItCanNeverReadAsAnOption()
    {
        var request = new ConversionRequest("-i", Output("mp3"), "wav", "mp3");

        await Assert.ThrowsAsync<ArgumentException>(() => _converter.ConvertAsync(request, Ct));
    }

    [Fact]
    public async Task AMissingFfmpeg_FailsTheJobWithAClearMessage()
    {
        var input = await SampleAsync("wav");
        var converter = new FfmpegConverter(Path.Combine(_directory, "no-such-ffmpeg"));

        var error = await Assert.ThrowsAsync<ConversionFailedException>(
            () => converter.ConvertAsync(new ConversionRequest(input, Output("mp3"), "wav", "mp3"), Ct));

        Assert.Contains("not available", error.Message, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData("mp4", "mp3", true)]
    [InlineData("mov", "gif", true)]
    [InlineData("flac", "ogg", true)]
    [InlineData("m4a", "mp3", true)]
    [InlineData("mp3", "mp4", false)]
    [InlineData("png", "jpg", false)]
    [InlineData("mp4", "avi", false)]
    public void CanConvert_CoversTheAudioAndVideoPairsOfTheCatalog(string source, string target, bool expected)
    {
        Assert.Equal(expected, _converter.CanConvert(source, target));
    }

    private string Output(string format) => Path.Combine(_directory, $"out-{Guid.NewGuid():N}.{format}");

    /// <summary>Makes a short sample with FFmpeg's built-in sources; skips the test without FFmpeg.</summary>
    private async Task<string> SampleAsync(
        string format, string extraArgument = "", string extraValue = "", int seconds = 2, string size = "160x120")
    {
        var path = Path.Combine(_directory, $"sample-{Guid.NewGuid():N}.{format}");
        var isVideo = format is "mp4" or "mkv";
        List<string> arguments = ["-hide_banner", "-loglevel", "error", "-y"];
        if (isVideo)
        {
            arguments.AddRange(["-f", "lavfi", "-i", $"testsrc=duration={seconds}:size={size}:rate=10"]);
        }

        arguments.AddRange(["-f", "lavfi", "-i", $"sine=frequency=440:duration={seconds}"]);
        if (isVideo)
        {
            arguments.AddRange(["-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest"]);
        }

        if (extraArgument.Length > 0)
        {
            arguments.AddRange([extraArgument, extraValue]);
        }

        arguments.Add(path);
        await RunFfmpegOrSkipAsync(arguments);
        return path;
    }

    private static async Task<double> DurationAsync(string path) =>
        double.Parse(await ProbeAsync(path, "format=duration"), System.Globalization.CultureInfo.InvariantCulture);

    /// <summary>Reads one value with ffprobe, found next to ffmpeg.</summary>
    private static async Task<string> ProbeAsync(string path, string entries, string option = "", string optionValue = "", string separator = "")
    {
        var ffprobe = Ffmpeg == "ffmpeg" ? "ffprobe" : Path.Combine(Path.GetDirectoryName(Ffmpeg)!, "ffprobe" + Path.GetExtension(Ffmpeg));
        var startInfo = new ProcessStartInfo(ffprobe) { RedirectStandardOutput = true, UseShellExecute = false };
        List<string> arguments = ["-v", "error", "-show_entries", entries, "-of", separator.Length > 0 ? $"csv=p=0:s={separator}" : "csv=p=0"];
        if (option.Length > 0)
        {
            arguments.AddRange([option, optionValue]);
        }

        arguments.Add(path);
        arguments.ForEach(startInfo.ArgumentList.Add);
        using var process = Process.Start(startInfo)!;
        var output = await process.StandardOutput.ReadToEndAsync(Ct);
        await process.WaitForExitAsync(Ct);
        return output.Trim();
    }

    private static async Task RunFfmpegOrSkipAsync(List<string> arguments)
    {
        var startInfo = new ProcessStartInfo(Ffmpeg) { RedirectStandardError = true, UseShellExecute = false };
        arguments.ForEach(startInfo.ArgumentList.Add);
        Process? process;
        try
        {
            process = Process.Start(startInfo);
        }
        catch (System.ComponentModel.Win32Exception)
        {
            Assert.Skip("FFmpeg is not installed: set FFMPEG_PATH or put ffmpeg on the PATH.");
            return;
        }

        using (process)
        {
            var errors = await process!.StandardError.ReadToEndAsync(Ct);
            await process.WaitForExitAsync(Ct);
            Assert.True(process.ExitCode == 0, $"Generating the sample failed: {errors}");
        }
    }
}
